import React, { useState, useContext } from 'react';
import FeedbackContext from '../context/FeedbackContext';

const FeedbackForm = () => {
  const [feedback, setFeedback] = useState({
    studentName: '',
    course: '',
    feedback: ''
  });
  const { courses } = useContext(FeedbackContext);

  const handleInputChange = (event) => {
    setFeedback({ ...feedback, [event.target.name]: event.target.value });
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    // Submit the feedback to the server or perform some other action
  };

  return (
    <form onSubmit={handleSubmit}>
      <label>
        Student Name:
        <input type="text" name="studentName" value={feedback.studentName} onChange={handleInputChange} />
      </label>
      <label>
        Course:
        <select name="course" value={feedback.course} onChange={handleInputChange}>
          {courses.map((course) => (
            <option key={course.id} value={course.id}>
              {course.name}
            </option>
          ))}
        </select>
      </label>
      <label>
        Feedback:
        <textarea name="feedback" value={feedback.feedback} onChange={handleInputChange} />
      </label>
      <button type="submit">Submit Feedback</button>
    </form>
  );
};

export default FeedbackForm;
