// Get the canvas and context
const canvas = document.getElementById('pendulum-canvas');
const ctx = canvas.getContext('2d');

// Set the canvas dimensions
canvas.width = 400;
canvas.height = 400;

// Set the initial angle and length of the pendulum
let initialAngle = 30;
let pendulumLength = 200;

// Set the gravity constant
const G = 0.98;

// Set the initial velocity
let velocity = 0;

// Create an array to store the pendulum's position and velocity at each frame
const frames = [];

// Function to update the pendulum's position and velocity
function updateFrame() {
  // Calculate the new position using the equations of motion
  const x = pendulumLength * Math.sin(initialAngle * Math.PI / 180);
  const y = -pendulumLength * Math.cos(initialAngle * Math.PI / 180);

  // Calculate the new velocity using the equations of motion
  velocity = -G * (Math.sin(initialAngle * Math.PI / 180) * Math.sqrt(Math.pow(pendulumLength, 2) + Math.pow(y, 2)) / pendulumLength);

  // Add the current position and velocity to the frames array
  frames.push({ x, y, velocity });

  // Request the next frame
  requestAnimationFrame(updateFrame);
}

// Function to draw the pendulum on the canvas
function drawPendulum() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw the pendulum bob
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  // Draw the pendulum string
  ctx.beginPath();
  ctx.moveTo(canvas.width / 2, canvas.height / 2);
  ctx.lineTo(canvas.width / 2 + x, canvas.height / 2 + y);
  ctx.stroke();

  // Update the initial angle for the next frame
  initialAngle -= velocity;
}

// Function to handle the button click
document.getElementById('release-button').addEventListener('click', () => {
  // Initialize the frames array
  frames = [];

  // Set the initial velocity to 0
  velocity = 0;

  // Set the initial angle to the user-input value
