import pygame
import random
import sys

# Initialize Pygame
pygame.init()

# Set up some constants
WIDTH = 800
HEIGHT = 600
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
RED = (255, 0, 0)
SPEED = 10

class Snake:
    def __init__(self):
        self.x = WIDTH // 2
        self.y = HEIGHT // 2
        self.size = 10
        self.speed = SPEED
        self.direction = "right"
        self.body = [(self.x, self.y)]

    def update(self):
        if self.direction == "right":
            self.x += self.speed
        elif self.direction == "left":
            self.x -= self.speed
        elif self.direction == "up":
            self.y -= self.speed
        elif self.direction == "down":
            self.y += self.speed

        self.body.insert(0, (self.x, self.y))
        self.body.pop()

    def grow(self):
        self.body.append(self.body[-1])

    def shrink(self):
        self.body.pop()

class SnakeFood:
    def __init__(self):
        self.x = random.randint(0, WIDTH - 10)
        self.y = random.randint(0, HEIGHT - 10)

    def update(self):
        if self.x < 0 or self.x > WIDTH - 10 or self.y < 0 or self.y > HEIGHT - 10:
            self.x = random.randint(0, WIDTH - 10)
            self.y = random.randint(0, HEIGHT - 10)

    def is_eaten(self, snake):
        return (self.x, self.y) in snake.body

class Game:
    def __init__(self):
        self.snake = Snake()
        self.snake_food = SnakeFood()
        self.score = 0

    def draw(self, screen):
        screen.fill(BLACK)
        pygame.draw.rect(screen, WHITE, (self.snake.x, self.snake.y, self.snake.size, self.snake.size))
        for x, y in self.snake.body[1:]:
            pygame.draw.rect(screen, WHITE, (x, y, self.snake.size, self.snake.size))
        pygame.draw.rect(screen, RED, (self.snake_food.x, self.snake_food.y, 10, 10))
        font = pygame.font.Font(None, 36)
        text = font.render(f"Score: {self.score}", True, WHITE)
        screen.blit(text, (10, 10))

    def update(self):
        self.snake.update()
        if self.snake.is_collision():
            self.game_over()
        if self.snake_food.is_eaten(self.snake):
            self.snake.grow()
            self.snake_food.update()
            self.score += 1
        if len(self.snake.body) > 5:
            self.snake.shrink()

    def game_over(self):
        print(f"Game Over! Final score: {self.score}")
        pygame.quit()
        sys.exit()

    def play(self):
        screen = pygame.display.set_mode((WIDTH, HEIGHT))
        clock = pygame.time.Clock()
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                elif event.type == pygame.KEYDOWN:
                    if event.key == pygame.K_UP and self.snake.direction != "down":
                        self.snake.direction = "up"
                    elif event.key == pygame.K_DOWN and self.snake.direction != "up":
                        self.snake.direction = "down"
                    elif event.key == pygame.K_LEFT and self.snake.direction != "right":
                        self.snake.direction = "left"
                    elif event.key == pygame.K_RIGHT and self.snake.direction != "left":
                        self.snake.direction = "right"

            self.update()
            self.draw(screen)
            pygame.display.update()
            clock.tick(10)

game = Game()
game.play()
