Here is a C# application that uses the 3 email accounts in rotation to send emails to a list of 100 subscribers:
```
using System;
using System.Net;
using System.Net.Mail;
using System.Threading;
using System.Collections.Generic;

namespace EmailSender
{
    class Program
    {
        static void Main(string[] args)
        {
            // List of email accounts
            string[] emailAccounts = { "email1@example.com", "email2@example.com", "email3@example.com" };

            // List of subscribers
            List<string> subscribers = new List<string>();
            for (int i = 0; i < 100; i++)
            {
                subscribers.Add($"subscriber{i}@example.com");
            }

            // Send emails
            int emailIndex = 0;
            foreach (string subscriber in subscribers)
            {
                UsingEmailAccount emailAccount = new UsingEmailAccount(emailAccounts[emailIndex]);
                emailAccount.SendEmail(subscriber, "Subject", "Body");
                emailIndex = (emailIndex + 1) % emailAccounts.Length;
                Thread.Sleep(100); // send emails with a short delay in between
            }
        }
    }

    class UsingEmailAccount
    {
        private string _emailAccount;

        public UsingEmailAccount(string emailAccount)
        {
            _emailAccount = emailAccount;
        }

        public void SendEmail(string to, string subject, string body)
        {
            using (MailMessage mail = new MailMessage())
            {
                mail.From = new MailAddress(_emailAccount);
                mail.To.Add(to);
                mail.Subject = subject;
                mail.Body = body;

                using (SmtpClient client = new SmtpClient())
                {
                    client.Send(mail);
                }
            }
        }
    }
}
```
