        // Execute the MongoDB query
        collection.find(query).forEach(doc -> {
            // Process the query result
            System.out.println(doc);
        });
    }

    private Document convertSQLtoMongoQuery(String sqlQuery) {
        // Split the SQL query into individual clauses
        String[] clauses = sqlQuery.split(" AND | OR ");

        Document query = new Document();
        for (String clause : clauses) {
            clause = clause.trim();
            if (clause.startsWith("(")) {
                clause = clause.substring(1, clause.lastIndexOf(")"));
            }

            // Handle various SQL clauses
            if (clause.startsWith("SELECT")) {
                // Handle SELECT clause
                query.put("projection", handleSelectClause(clause));
            } else if (clause.startsWith("FROM")) {
                // Handle FROM clause
                query.put("filter", handleFromClause(clause));
            } else if (clause.startsWith("WHERE")) {
                // Handle WHERE clause
                query.put("filter", handleWhereClause(clause));
            } else if (clause.startsWith("GROUP BY")) {
                // Handle GROUP BY clause
                query.put("group", handleGroupByClause(clause));
            } else if (clause.startsWith("HAVING")) {
                // Handle HAVING clause
                query.put("filter", handleHavingClause(clause));
            } else if (clause.startsWith("ORDER BY")) {
                // Handle ORDER BY clause
                query.put("sort", handleOrderByClause(clause));
            } else if (clause.startsWith("LIMIT")) {
                // Handle LIMIT clause
                query.put("limit", handleLimitClause(clause));
            } else if (clause.startsWith("OFFSET")) {
                // Handle OFFSET clause
                query.put("skip", handleOffsetClause(clause));
            }
        }

        return query;
    }

    private Document handleSelectClause(String clause) {
        // Extract the select fields
        String[] fields = clause.split(", ");
        Document projection = new Document();
        for (String field : fields) {
            projection.put(field.trim(), 1);
        }
        return projection;
    }

    private Document handleFromClause(String clause) {
        // Extract the collection name
        String collectionName = clause.split("FROM")[1].trim();
        return new Document("_collection", collectionName);
    }

    private Document handleWhereClause(String clause) {
        // Extract the filter criteria
        String[] criteria = clause.split("WHERE")[1].trim().split(" AND | OR ");
        Document filter = new Document();
        for (String criterion : criteria) {
            String[] parts = criterion.split("=");
            filter.put(parts[0].trim(), parts[1].trim());
        }
        return filter;
    }

    private Document handleGroupByClause(String clause) {
        // Extract the group by fields
        String[] fields = clause.split("GROUP BY")[1].trim().split(", ");
        Document group = new Document();
        for (String field : fields) {
            group.put(field.trim(), "$" + field.trim());
        }
        return group;
    }

    private Document handleHavingClause(String clause) {
        // Extract the having criteria
        String[] criteria = clause.split("HAVING")[1].trim().split(" AND | OR ");
        Document filter = new Document();
        for (String criterion : criteria) {
            String[] parts = criterion.split("=");
            filter.put(parts[0].trim(), parts[1].trim());
        }
        return filter;
    }

    private Document handleOrderByClause(String clause) {
        // Extract the sort order
        String[] fields = clause.split("ORDER BY")[1].trim().split(", ");
        Document sort = new Document();
        for (String field : fields) {
            String[] parts = field.split(" ");
            sort.put(parts[0].trim(), parts[1].trim().equals("ASC") ? 1 : -1);
        }
        return sort;
    }

    private Document handleLimitClause(String clause) {
        // Extract the limit
        String[] parts = clause.split("LIMIT")[1].trim().split(" ");
        return new Document("$limit", Integer.parseInt(parts[0].trim()));
    }

    private Document handleOffsetClause(String clause) {
        // Extract the offset
        String[] parts = clause.split("OFFSET")[1].trim().split(" ");
        return new Document("$skip", Integer.parseInt(parts[0].trim()));
    }
}
