  async use(req: Request, res: Response, next: NextFunction) {
    const token = req.signedCookies['jwt'];
    if (!token) {
      return res.status(401).send({ message: 'Unauthorized' });
    }

    try {
      const decoded = jwt.verify(token, 'your-secret-key');
      req.user = decoded;
      next();
