                return fs::last_write_time(a) < fs::last_write_time(b);
            });

            // Rename files with 3-digit numbers
            int counter = 0;
            for (const fs::path& file : files) {
                std::string newFileName = "file_" + std::to_string(counter++) + "_" + file.filename().string();
                fs::rename(file, dirPath / newFileName);
            }
        } catch (fs::filesystem_error& e) {
            errors.push_back(e);
        }
    }

    // Print any errors that occurred
    if (!errors.empty()) {
        std::cout << "Renaming errors: " << std::endl;
        for (const auto& error : errors) {
            std::cout << error.what() << std::endl;
        }
    }
