```
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC721/SafeERC721.sol";
import "@openzeppelin/contracts/utils/Counters.sol";

contract MyNFTCollection {
    using Counters for Counters.Counter;
    Counters.Counter private _tokenIds;

    address public owner;
    string public name;
    string public symbol;
    uint public totalSupply;

    constructor(string memory _name, string memory _symbol) public {
        owner = msg.sender;
        name = _name;
        symbol = _symbol;
        totalSupply = 1000; // fixed supply of 1000 NFTs
    }

    function mint(address to, uint256 tokenId) public {
        require(msg.sender == owner, "Only the owner can mint NFTs");
        require(tokenId <= totalSupply, "NFT ID exceeds the total supply");
        _tokenIds.increment();
        _mint(to, tokenId);
    }

    function _mint(address to, uint256 tokenId) internal {
        emit Transfer(address(0), to, tokenId);
    }

    function burn(uint256 tokenId) public {
        require(msg.sender == owner, "Only the owner can burn NFTs");
        require(tokenId <= totalSupply, "NFT ID exceeds the total supply");
        _tokenIds.decrement();
        _burn(tokenId);
    }

    function _burn(uint256 tokenId) internal {
        emit Transfer(to, address(0), tokenId);
    }

    function getOwner() public view returns (address) {
        return owner;
    }

    function getTokenId(uint256 index) public view returns (uint256) {
        return _tokenIds.current() + index;
    }

    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
}
```
