**ShopActivity.java**
```java
import android.app.Activity;
import android.content.ContentValues;
import android.content.Context;
import android.content.Intent;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;
import android.os.Bundle;
import android.view.View;
import android.widget.AdapterView;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.EditText;
import android.widget.ListView;
import android.widget.Toast;

import java.util.ArrayList;
import java.util.List;

public class ShopActivity extends Activity {

    private static final String DATABASE_NAME = "shop.db";
    private static final int DATABASE_VERSION = 1;

    private SQLiteDatabase db;
    private SQLiteOpenHelper helper;

    private ListView listView;
    private EditText itemEditText;
    private Button addButton;

    private List<Item> items = new ArrayList<>();
    private ItemAdapter adapter;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_shop);

        helper = new SQLiteOpenHelper(this, DATABASE_NAME, null, DATABASE_VERSION) {
            @Override
            public void onCreate(SQLiteDatabase db) {
                db.execSQL("CREATE TABLE items (_id INTEGER PRIMARY KEY, name TEXT, quantity INTEGER)");
            }

            @Override
            public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
                db.execSQL("DROP TABLE IF EXISTS items");
                onCreate(db);
            }
        };

        db = helper.getWritableDatabase();

        listView = (ListView) findViewById(R.id.listView);
        itemEditText = (EditText) findViewById(R.id.itemEditText);
        addButton = (Button) findViewById(R.id.addButton);

        adapter = new ItemAdapter(this, items);
        listView.setAdapter(adapter);

        listView.setOnItemClickListener(new AdapterView.OnItemClickListener() {
            @Override
            public void onItemClick(AdapterView<?> parent, View view, int position, long id) {
                Item item = items.get(position);
                Intent intent = new Intent(ShopActivity.this, EditItemActivity.class);
                intent.putExtra("item", item);
                startActivityForResult(intent, 1);
            }
        });

        addButton.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                addItem();
            }
        });
    }

    private void addItem() {
        String name = itemEditText.getText().toString();
        int quantity = 1;

        ContentValues values = new ContentValues();
        values.put("name", name);
        values.put("quantity", quantity);

        db.insert("items", null, values);

        items.add(new Item(name, quantity));
        adapter.notifyDataSetChanged();

        itemEditText.setText("");
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        if (requestCode == 1 && resultCode == RESULT_OK) {
            Item item = data.getParcelableExtra("item");
            items.set(item.getId(), item);
            adapter.notifyDataSetChanged();
        }
    }

    private class ItemAdapter extends ArrayAdapter<Item> {
        public ItemAdapter(Context context, List<Item> items) {
            super(context, 0, items);
        }

        @Override
        public View getView(int position, View convertView, ViewGroup parent) {
            View view = convertView;
            if (view == null) {
                view = getLayoutInflater().inflate(R.layout.list_item, parent, false);
            }

            Item item = getItem(position);
            ((TextView) view.findViewById(R.id.nameTextView)).setText(item.getName());
            ((EditText) view.findViewById(R.id.quantityEditText)).setText(String.valueOf(item.getQuantity()));

            return view;
        }
    }

    public class Item {
        private int id;
        private String name;
        private int quantity;

        public Item(String name, int quantity) {
            this.name = name;
            this.quantity = quantity;
        }

        public int getId() {
            return id;
        }

        public void setId(int id) {
            this.id = id;
        }

        public String getName() {
            return name;
        }

        public int getQuantity() {
            return quantity;
        }
    }
}
