// Retrieve form elements
const claimIdInput = document.getElementById('claim-id');
const claimDateInput = document.getElementById('claim-date');
const amountInput = document.getElementById('amount');
const descriptionTextarea = document.getElementById('description');
const submitButton = document.getElementById('submit-claim');

// Submit claim function
function submitClaim() {
  // Validate form inputs
  if (!claimIdInput.value || !claimDateInput.value || !amountInput.value || !descriptionTextarea.value) {
    alert('Please fill out all required fields');
    return;
  }

  // Create a JSON object with form data
  const claimData = {
    id: claimIdInput.value,
    date: claimDateInput.value,
    amount: amountInput.value,
    description: descriptionTextarea.value
  };

  // Send a POST request to the server to submit the claim
  fetch('/submit-claim', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(claimData)
  })
  .then(response => response.json())
  .then(data => {
    if (data.success) {
      alert('Claim submitted successfully!');
    } else {
      alert('Error submitting claim: ' + data.error);
    }
  })
  .catch(error => console.error(error));
}

// Attach event listener to submit button
submitButton.addEventListener('click', submitClaim);
