  heroId: string;
}

const HeroProfilePage: React.FC<HeroProfileProps> = ({ heroId }) => {
  const [hero, setHero] = useState<Hero | null>(null);
  const [ability, setAbility] = useState({
    name: '',
    value: 0,
  });
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get(`https://hahow-recruit.herokuapp.com/heroes/${heroId}`)
      .then(response => response.data)
      .then(data => setHero(data))
      .finally(() => setLoading(false));
  }, [heroId]);

  const handleAbilityUpdate = (name: string, value: number) => {
    setAbility({
      name,
      value,
    });
  };

  const handleSubmit = () => {
    axios.patch(`https://hahow-recruit.herokuapp.com/heroes/${heroId}/profile`, { abilities: [{ name: ability.name, value: ability.value }] })
      .then(response => console.log(response.data))
