            <ul>
              {hero.profile.abilities.map((ability, index) => (
                <li key={index}>
                  <label>
                    {ability.name}
                    <input
                      type="number"
                      value={ability.value}
                      onChange={event => handleAbilityUpdate(ability.name, parseInt(event.target.value, 10))}
                    />
                    <button onClick={() => handleAbilityUpdate(ability.name, ability.value + 1)}>Increment</button>
                    <button onClick={() => handleAbilityUpdate(ability.name, ability.value - 1)}>Decrement</button>
                  </label>
                </li>
              ))}
            </ul>
            <p>Remaining points: {hero.profile.abilities.reduce((acc, ability) => acc + ability.value, 0)}</p>
          </div>
          <button onClick={handleSubmit}>Save Changes</button>
        </div>
      )}
    </div>
  );
};

export default HeroProfilePage;
